begin;

-- =========================================================
-- MIGRATION 4E–4G
-- Generated from the user's actual QA/QC checklist attachments,
-- KAK survey pendahuluan, and SMD validation form.
-- =========================================================

-- 4E. Enrich checklist item structure
alter table public.qaqc_checklist_item
    add column if not exists section text,
    add column if not exists check_type text not null default 'MANUAL_CHECK',
    add column if not exists opsi jsonb not null default '[]'::jsonb,
    add column if not exists satuan text,
    add column if not exists rule_key text,
    add column if not exists sumber_bagian text,
    add column if not exists source_order integer,
    add column if not exists metadata jsonb not null default '{}'::jsonb;

create unique index if not exists uq_qaqc_checklist_item_template_code
on public.qaqc_checklist_item(id_template, kode_item)
where kode_item is not null;

-- IRI consistency is embedded in the IRI calibration/validation document.
insert into public.qaqc_checklist_template (
    id_survei,fase,nama_kegiatan,jenis_kegiatan,kode_kegiatan,urutan,aktif,
    frekuensi,trigger_type,aktor_pengisi,aktor_review,requires_periode,
    sumber_referensi,sumber_dokumen,versi,catatan_template
)
values (
    'S01',3,'Pemeriksaan Konsistensi / Repeatability IRI','CHECKLIST','KONSISTENSI',10,true,
    'BERKALA','PERIODE_SURVEI','KONSULTAN','PIC_BALAI',true,
    'Lampiran Checklist IRI','CHECKLIST KALIBRASI DAN VALIDASI.docx','IRI',
    'Bagian B. CHECKLIST KONSISTENSI berada pada dokumen kalibrasi dan validasi IRI.'
)
on conflict do nothing;

-- 4F. Global Survey Pendahuluan template from KAK
insert into public.qaqc_checklist_template (
    id_survei,fase,nama_kegiatan,jenis_kegiatan,kode_kegiatan,urutan,aktif,
    frekuensi,trigger_type,aktor_pengisi,aktor_review,requires_periode,
    sumber_referensi,sumber_dokumen,versi,catatan_template
)
values (
    null,1,'Checklist Survei Pendahuluan','CHECKLIST','SURVEI_PENDAHULUAN',20,true,
    'SEKALI','SEBELUM_SURVEI_UTAMA','KONSULTAN','PIC_BALAI',false,
    'KAK Inspeksi Kondisi Jaringan Jalan TA 2025','Update Survey Pendahuluan,KAK_Inspeksi_Kondisi_Jaringan_Jalan_TA_2025_Lumsum Rev2.docx','KAK_2025',
    'Kegiatan Survei Pendahuluan sebelum survei utama.'
)
on conflict do nothing;

-- 4G. Validation rule registry
create table if not exists public.validation_rule (
    kode_rule text primary key,
    id_survei text references public.ref_jenis_survei(id_survei) on update cascade on delete set null,
    fase integer not null check (fase between 1 and 4),
    kode_kegiatan text references public.ref_kegiatan_qaqc(kode_kegiatan) on update cascade on delete set null,
    parameter text not null,
    rule_type text not null,
    operator text,
    nilai_batas_num numeric,
    nilai_batas_text text,
    satuan text,
    severity text,
    sumber_referensi text not null,
    aktif boolean not null default true,
    metadata jsonb not null default '{}'::jsonb,
    created_at timestamptz not null default now()
);


