-- Convenience view for implementation/debugging
create or replace view public.vw_qaqc_template_item_count as
select
    t.id_template,
    t.id_survei,
    t.versi,
    t.fase,
    t.kode_kegiatan,
    t.nama_kegiatan,
    t.aktif,
    count(i.id_item) as jumlah_item
from public.qaqc_checklist_template t
left join public.qaqc_checklist_item i on i.id_template=t.id_template
group by t.id_template,t.id_survei,t.versi,t.fase,t.kode_kegiatan,t.nama_kegiatan,t.aktif;

commit;

